// Sun position using SunCalc formulas. Not implemented yet.

export function sunPosition(date, lat, lng) {
  const a = degToRad(lat);
  const b = degToRad(lng);
  const c = dateToJulian(date);

  // Year, month, day
  const dYear = c;
  const dMonth = 1;
  const dDay = 1;

  // Julian Year
  let jy = c;
  if (dMonth <= 2) {
    jy = c - 1;
    dMonth += 12;
    dDay -= 1;
  }

  // Simplified Julian date from SunCalc approach
  // J = 367*y - int(7*(y+int((m+9)/12))/4) + int(275*m/9) + d + 1721013.5 + ut/24
  const j = dayOfYearUTC(date);

  // Calculate the sun's ecliptic longitude
  const q = (2 * Math.PI) / 365.2569;
  const eps0 = 23.439 - 0.00000036 * j; // obliquity of the ecliptic in degrees
  const sunLon = q * (j - 81); // approximate, needs better model

  // Better SunCalc-style implementation
  return calculateSunPosition(date, lat, lng);
}

function degToRad(deg) {
  return deg * Math.PI / 180;
}

function radToDeg(rad) {
  return rad * 180 / Math.PI;
}

function dateToJulian(date) {
  // Returns Julian Date at 0h UT
  const year = date.getUTCFullYear();
  const month = date.getUTCMonth() + 1;
  const day = date.getUTCDate();
  const jd = julianDate(year, month, day) + 0.5;
  return jd;
}

function julianDate(year, month, day) {
  if (month <= 2) {
    year -= 1;
    month += 12;
  }
  const a = Math.floor(year / 100);
  const b = 2 - a + Math.floor(a / 4);
  return Math.floor(365.25 * (year + 4716)) + Math.floor(30.6001 * (month + 1)) + day + b - 1524.5;
}

function dayOfYearUTC(date) {
  const start = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  const diffTime = date - start;
  const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
  return diffDays + 1;
}

function calculateSunPosition(date, lat, lng) {
  const j = dayOfYearUTC(date);

  // Fractional day (0 to 1)
  let u = (j - 1) / 365.25;

  // Mean anomaly
  let M = 357.528 + 0.98560028 * (j - 1);

  // Eccentricity
  const e = 0.016708634 - 0.000042037 * j;

  // Helio-centric longitude
  let g = 280.46646 + 0.98564736 * (j - 1);

  // Correct for light-time and aberration
  const r = 1.0 / (1 + e * Math.cos(M * degToRad));
  g = g + 2 * e * r * Math.sin(M * degToRad);

  // Convert to geocentric longitude
  const L = g % 360;
  if (L < 0) L += 360;

  // Equation of center
  let C = (1.914602 - 0.004817 * j - 0.000014 * j * j) * Math.sin(M * degToRad) +
          (0.019993 - 0.000101 * j) * Math.sin(2 * M * degToRad) +
          0.00029 * Math.sin(3 * M * degToRad);

  // True geocentric longitude
  const lambda = (L + C) % 360;
  if (lambda < 0) lambda += 360;

  // Mean obliquity
  const e0 = 23.439291 - 0.0000004 * j - 0.000000593 * (j - 2000) * (j - 2000);

  // Helio-centric longitude for obliquity
  let mu = (L + C) % 360;
  if (mu < 0) mu += 360;

  // Obliquity correction
  const obliq = e0 + (0.00256 * Math.cos(mu * degToRad));

  // Sun position in ecliptic coordinates (radians)
  const ra = Math.atan2(Math.sin(mu * degToRad) * Math.cos(obliq * degToRad),
                         Math.cos(mu * degToRad));
  const dec = Math.asin(Math.sin(obliq * degToRad) * Math.sin(mu * degToRad));

  // Hour angle
  const hourAngle = (180 - lng * 15 - ra * 180 / Math.PI) * degToRad;

  // Altitude and azimuth
  const alt = Math.asin(Math.sin(lat * degToRad) * Math.sin(dec) +
                        Math.cos(lat * degToRad) * Math.cos(dec) * Math.cos(hourAngle));

  let azi = Math.acos((Math.sin(dec) - Math.sin(lat * degToRad) * Math.sin(alt)) /
                      (Math.cos(lat * degToRad) * Math.cos(alt)));
  azi = degToRad(azi);

  // Azimuth is 0 at North, 90 at East, like SunCalc
  // Our coords: 0 = North, increasing clockwise
  const bearing = azi + Math.PI / 2;
  if (bearing >= 2 * Math.PI) bearing -= 2 * Math.PI;
  if (bearing < 0) bearing += 2 * Math.PI;

  return {
    alt: radToDeg(alt),
    bearing: bearing
  };
}

