export function sunPosition(date, lat, lng) {
  const a = degToRad(lat);
  const b = degToRad(lng);
  const j = julianDayNumber(date);

  // Julian year, month, day
  let jy = j;
  if (getUTCMonth(date) <= 2) {
    jy = j - 1;
    setUTCMonth(date, getUTCMonth(date) + 12);
    setDate(date, getDate(date) - 1);
  }

  // Julian Date at 0h UT
  const jd0 = julianDayDate(jy, getUTCMonth(date), getDate(date));

  // Fractional day (0 to 1)
  let u = (j - 1) / 365.25; // u = (JD - 1) / 365.25 - fractional part handling

  // Mean anomaly
  let M = 357.528 + 0.98560028 * (j - 1);

  // Eccentricity
  let e = 0.016708634 - 0.000042037 * j;

  // Correction for light-time and aberration
  let g = 280.46646 + 0.98564736 * (j - 1);
  let r = 1.0 / (1.0 + e * cos(M * degToRad));
  g = g + 2 * e * r * sin(M * degToRad);

  // Convert to geocentric longitude
  let L = g % 360;
  if (L < 0) L += 360;

  // Equation of center
  let C = (1.914602 - 0.004817 * j - 0.000014 * j * j) * sin(M * degToRad) +
          (0.019993 - 0.000101 * j) * sin(2 * M * degToRad) +
          0.00029 * sin(3 * M * degToRad);

  // True geocentric longitude
  let lambda = (L + C) % 360;
  if (lambda < 0) lambda += 360;

  // Mean obliquity
  let e0 = 23.439291 - 0.0000004 * j - 0.000000593 * (j - 2000) * (j - 2000);

  // Helio-centric longitude for obliquity
  let mu = (L + C) % 360;
  if (mu < 0) mu += 360;

  // Obliquity correction
  e0 = e0 + 0.00256 * cos(mu * degToRad);

  // Sun position in ecliptic coordinates
  const ra = atan2(sin(mu * degToRad) * cos(e0 * degToRad), cos(mu * degToRad));
  const dec = asin(sin(e0 * degToRad) * sin(mu * degToRad));

  // Hour angle
  let hourAngle = (180 - b * 15 - ra * 180 / Math.PI) * degToRad;

  // Altitude
  let alt = asin(sin(a) * sin(dec) + cos(a) * cos(dec) * cos(hourAngle));

  // Azimuth
  let azimuth = acos((sin(dec) - sin(a) * sin(alt)) / (cos(a) * cos(alt)));
  azimuth += Math.PI / 2; // 0 = North, increasing clockwise
  if (azimuth >= 2 * Math.PI) azimuth -= 2 * Math.PI;
  if (azimuth < 0) azimuth += 2 * Math.PI;

  return {
    alt: radToDeg(alt),
    bearing: azimuth
  };
}

