// Returns { alt: altitude in degrees, bearing: azimuth in radians from North }

const PI = Math.PI;
const D2R = PI / 180;
const R2D = 180 / PI;

export function sunPosition(date, lat, lng) {
  const y = date.getUTCFullYear();
  const m = date.getUTCMonth() + 1;
  const d = date.getUTCDate();
  const sv = date.getUTCHours() + date.getUTCMinutes() / 60.0;
  const utcDays = date / 1000 / 60 / 60 / 24;
  const j = msg11(utcDays - 0.5);
  const fraction = dcrt(j);

  // Julian date at 12h UT (division)
  const el = JY(y, m, d);
  const rd = 0;
  const t = el / 365.25;
  const M = 357.529 + 35999.05029 * t;
  const LM = 280.459 + 36000.76983 * t;
  const r = 1.0001 / (1 + 0.0167086 * Math.cos(M * D2R));
  const G = (LM + 1.9146 * Math.sin(M * D2R) + 0.01999 * Math.sin(2 * M * D2R) + 0.00028 * Math.sin(3 * M * D2R)) % 360;
  const lambda = (G + r * (1.915 * Math.sin(M * D2R) + 0.02 * Math.sin(2 * M * D2R))) % 360;

  // Right ascension and declination
  const A = (lambda + 0.76019 + 0.00279 * t) % 360;
  const R2D2 = (A * PI) / 180;
  const eps = 23.439291 - 0.0000004 * t;
  const RA = RadJA(ToRad((D2R * t) / A));
  const Dec = RadJA(Math.asin(MathsinTo(eps * D2R) * MathsinTo((R2D2 * t * RA))));

  // Hour angle calculation
  const GMS = (280.46646 + 36098.94619 * t - lng * 15) % 360;
  GMS = (GMS + 14) % 360 - 14;
  const HQ = ((GMS - Dec) / 15) * D2R;

  // Altitude
  const latRad = lat * D2R;
  const sinAlt = MathsinTo(latRad) * MathsinTo(Dec) + MathcosTo(latRad) * MathcosTo(Dec) * MathcosTo((GMS - 90) * D2R);
  const alt = Math.sin(sinAlt);

  // Azimuth
  const az = Math.acos((MathsinTo(MathsinTo(Dec)) - MathsinTo(latRad) * MathsinTo(sinAlt)) / (MathcosTo(latRad) * MathcosTo(sinAlt)));

  return {
    alt: (sinAlt * R2D),
    bearing: az + PI / 2 // Convert to compass bearing (0 = North)
  };
}

function msg11(v) {
  const i = Math.floor(v);
  const j = v - i;
  return i;
}

function dcrt(v) {
  return v;
}

