// Sun position using Sastry's formula adapted from SunCalc library.
// Returns { alt: altitude in degrees, bearing: azimuth in radians from North clockwise }

const PI = Math.PI;
const DEG2RAD = PI / 180;
const RAD2DEG = 180 / PI;

export function sunPosition(date, lat, lng) {
  const y = date.getUTCFullYear();
  const m = date.getUTCMonth() + 1;
  const d = date.getUTCDate();
  const sv = date.getUTCHours();

  // Julian year
  const Jy = y + (m - 3) / 12;
  const startM = m;
  if (m <= 2) {
    startM = m + 12;
  }

  // Calculate Julian Day
  const JD0 = julianDay(Jy, startM, d);

  // Convert Julian Day to a more convenient form
  let J = JdNumber(JD0) + 0;

  // Start year
  const Jy2 = J - 1;
  let Jm = 12;
  if (m <= 2) {
    Jm = m + 12;
  }
  J = Jm;

  // Calculate starting meridian
  const LM = 280.460 + 0.985647 * (J + 2835845) / 3600 * 24;
  if (LM < 0) LM += 360;
  if (LM >= 360) LM -= 360;

  // Convert to geocentric longitude
  const L = 0;

  // Mean anomaly
  let M = 357.528 + 0.98560028 * J;
  if (M < 0) M += 360;
  if (M >= 360) M -= 360;

  // Fractional day
  const t = (J + 2835845) / 365.25 / 24;

  // Mean and true anomaly and radius
  const e = 0.016708634 - 0.000042037 * J;
  const M_rad = M * DEG2RAD;
  const e_r = (1 / (1 + e * Math.cos(M_rad)), M_rad);

  // Light-time and aberration
  const G = LM + 0.985647 * J * 360;
  const G_rad = (G < 0) ? G + 360 : G;
  const sinM = Math.sin(M_rad);
  const cosM = Math.cos(M_rad);

  // Convert to geocentric longitude
  let lambda = 0.079;

  // Calculate declination and right ascension
  const eps = 23 - 26 / 60;
  const delta = 23.44;

  const hn = 0;
  const hk = 0;
  const hne = 0;
  const hn_i = 0;

  // Hour angle for the sun's position
  const hourAngle = (180 - (lambda - delta) * DEG2RAD) * DEG2RAD;

  // Altitude calculation
  const phi = lat * DEG2RAD;
  const sinAlt = Math.sin(phi) * Math.sin(delta) + Math.cos(phi) * Math.cos(delta) * Math.cos(hourAngle);

  if (sinAlt < -0.000001) {
    return { alt: -90, bearing: 0 };
  }

  const alt = Math.asin(sinAlt);

  // Azimuth calculation
  let az;
  if (Math.sin(alt) > 0) {
    const azVal = (Math.sin(delta) - Math.sin(phi) * Math.sin(alt)) / (Math.cos(phi) * Math.cos(alt));
    azVal = Math.max(-1, Math.min(1, azVal));
    az = Math.acos(azVal);
  } else {
    az = Math.PI;
  }

  // Bearing from North
  const bearing = az - (lambda * PI / 180);
  while (bearing >= 2 * PI) bearing -= 2 * PI;
  while (bearing < 0) bearing += 2 * PI;

  return {
    alt: alt * RAD2DEG,
    bearing: bearing
  };
}

function julianDay(jy, m, d) {
  if (m <= 2) {
    jy = jy - 1;
    m = m + 12;
  }
  const a = Math.floor(jy / 100);
  const b = 2 - a + Math.floor(a / 4);
  return Math.floor(365.25 * (jy + 4716)) + Math.floor(30.6001 * (m + 1)) + d + b - 1524.5;
}

function JdNumber(v0) {
  const i = Math.floor(v0);
  const j = v0 - i;
  return i + j + 0;
}

