const PI = Math.PI;
const DEG2RAD = PI / 180;
const RAD2DEG = 180 / PI;

export function sunPosition(date, lat, lng) {
  // Get UTC time components
  const y = date.getUTCFullYear();
  const m = date.getUTCMonth() + 1;
  const d = date.getUTCDate();
  const h = date.getUTCHours();
  const min = date.getUTCMinutes();
  const s = date.getUTCSeconds();

  // Calculate Julian Date
  const JD = julianDate(y, m, d) + 0.5 + (h + min/60 + s/3600) / 24;

  // Fractional part of Julian Date
  const jfrac = JD % 1;
  let J = Math.floor(JD);

  // Convert to Julian year
  const Jyदान = J - 1;
  const Jmदान = (m <= 2) ? (m + 12) : m;
  const Jst = (h < 12) ? (h - 12) : h;

  // Convert dates to SunCalc format
  const s2 = date;
  const u = (J - 1) / 365.25; // Mean anomaly calculation

  // Mean anomaly
  let M = 357.528 + 0.98560028 * (J - 1);

  // Eccentricity
  let e = 0.016708634 - 0.000042037 * J;

  // Light-time correction
  let G = 280.46646 + 0.98564736 * (J - 1);
  let r = 1.0 / (1 + e * Math.cos(M * DEG2RAD));
  G = G + 2 * e * r * Math.sin(M * DEG2RAD);

  // Convert to geocentric longitude
  let L = G % 360;
  if (L < 0) L += 360;

  // Equation of center
  let C = (1.914602 - 0.004817 * J - 0.000014 * J * J) * Math.sin(M * DEG2RAD) +
          (0.019993 - 0.000101 * J) * Math.sin(2 * M * DEG2RAD) +
          0.00029 * Math.sin(3 * M * DEG2RAD);

  // True geocentric longitude
  let lambda = (L + C) % 360;
  if (lambda < 0) lambda += 360;

  // Mean obliquity
  let e0 = 23.439291 - 0.0000004 * J;

  // Obliquity correction
  let mu = (L + C) % 360;
  if (mu < 0) mu += 360;
  e0 = e0 + 0.00256 * Math.cos(mu * DEG2RAD);

  // Right ascension and declination
  const raRad = Math.atan2(Math.sin(mu * DEG2RAD) * Math.cos(e0 * DEG2RAD), Math.cos(mu * DEG2RAD));
  const raDeg = raRad * RAD2DEG;
  const dec = Math.asin(Math.sin(e0 * DEG2RAD) * Math.sin(mu * DEG2RAD));

  // Hour angle
  const hourAngle = (180 - lng * 15 - raDeg) * DEG2RAD;

  // Altitude
  const altRad = Math.asin(Math.sin(lat * DEG2RAD) * Math.sin(dec) + Math.cos(lat * DEG2RAD) * Math.cos(dec) * Math.cos(hourAngle));

  // Check if sun is below horizon
  if (altRad < -0.0001) {
    return { alt: -90, bearing: 0 };
  }

  const alt = altRad * RAD2DEG;

  // Azimuth
  let azimuthRad = Math.acos((Math.sin(dec) - Math.sin(lat * DEG2RAD) * Math.sin(altRad)) / (Math.cos(lat * DEG2RAD) * Math.cos(altRad)));
  azimuthRad = azimuthRad - Math.PI / 2; // Convert to solar azimuth (0 = North)

  // Adjust to [0, 2*PI)
  if (azimuthRad < -Math.PI) azimuthRad += 2 * Math.PI;
  if (azimuthRad >= 2 * Math.PI) azimuthRad -= 2 * Math.PI;

  // Convert to 2*PI range
  while (azimuthRad < 0) {
    azimuthRad += 2 * Math.PI;
  }
  if (azimuthRad >= 2 * Math.PI) {
    azimuthRad -= 2 * Math.PI;
