  // Convert to radians
  const lngRad = lng * A_DEG2RAD;

  // Hour angle = (GMST0 - longitude) - RA
  let hourAngle = (gmst0Rad - lngRad) - raRad;

  // Normalize to [-PI, PI]
  while (hourAngle > A_PI) hourAngle -= 2 * A_PI;
  while (hourAngle < -A_PI) hourAngle += 2 * A_PI;

