  const latRad = lat * A_DEG2RAD;
  let altRad = Math.asin(Math.sin(latRad) * Math.sin(decRad) + Math.cos(latRad) * Math.cos(decRad) * Math.cos(hourAngle));

  // Check if sun is below horizon
  if (altRad < -0.0001) {
    return { alt: -90, bearing: 0 };
  }

  const alt = altRad * A_RAD2DEG;

  // Azimuth
  let azimuthRad;
  if (Math.sin(altRad) > 0) {
