  }

  // Azimuth = 0 at North, clockwise
  // Current azimuth is from the sun's point of view, so adjust
  let azFromNorth = (azimuthRad + A_PI - gmst0Rad) % (2 * A_PI);

  // Normalize bearing to [0, 2*PI)
  if (azFromNorth < 0) azFromNorth += 2 * A_PI;
  if (azFromNorth >= 2 * A_PI) azFromNorth -= 2 * A_PI;

  return {
    alt: alt,
    bearing: azFromNorth
