  // Mean anomaly
  let M = 357.528 + 0.98560028 * (JD0 - 2451545);
  while (M < 0) M += 360;
  while (M >= 360) M -= 360;

  // Eccentricity
  let e = 0.016708634;

  // Light-time correction
  let G = 280.46646 + 0.98564736 * (JD0 - 2451545);
  let r = 1.0 / (1 + e * Math.cos(M * DEG2RAD));
  G = G + 2 * e * r * Math.sin(M * DEG2RAD);

  // Convert to geocentric longitude
  let L = G % 360;
  if (L < 0) L += 360;

  // Equation of center
  let C = (1.914602 * Math.sin(M * DEG2RAD)) +
          (0.02 * Math.sin(2 * M * DEG2RAD));

  // True geocentric longitude
  let lambda = (L + C) % 360;
  if (lambda < 0) lambda += 360;

  // Mean obliquity
  let e0 = 23.439291;

  // Obliquity correction
  let mu = (L + C) % 360;
  if (mu < 0) mu += 360;
  e0 = e0 + 0.00256 * Math.cos(mu * DEG2RAD);

  // Right ascension and declination
  const raRad = Math.atan2(Math.sin(mu * DEG2RAD) * Math.cos(e0 * DEG2RAD), Math.cos(mu * DEG2RAD));
  const raDeg = raRad * RAD2DEG;
  const decRad = Math.asin(Math.sin(e0 * DEG2RAD) * Math.sin(mu * DEG2RAD));

  // Hour angle calculation
  // Local hour angle = GST - RA (in radians)
  // GST = GMST0 + ω * (UT1)

  // Calculate GMST0 (Greenwich Mean Sidereal Time at 0h UT for date)
  const jdDate = JD0 - 2451545.0;
  const gmst0 = (280.46646 + 36098.94619 * jdDate / 24) % 360;
  const gmst0Rad = gmst0 * DEG2RAD;

  // Convert to radians
  const lngRad = lng * DEG2RAD;

  // Hour angle = (GMST0 - longitude) - RA
  const hourAngle = (gmst0Rad - lngRad) - raRad;

  // Normalize to [-PI, PI]
  while (hourAngle > PI) hourAngle -= 2 * PI;
  while (hourAngle < -PI) hourAngle += 2 * PI;

